#[inline]
unsafe extern "C" fn hdd_stats_add(mut dst: *mut hddstats, mut src: *mut hddstats) {
    unsafe {
        (*dst).rbytes = (*dst).rbytes.wrapping_add((*src).rbytes);
        (*dst).wbytes = (*dst).wbytes.wrapping_add((*src).wbytes);
        (*dst).nsecreadsum = (*dst).nsecreadsum.wrapping_add((*src).nsecreadsum);
        (*dst).nsecwritesum = (*dst).nsecwritesum.wrapping_add((*src).nsecwritesum);
        (*dst).nsecfsyncsum = (*dst).nsecfsyncsum.wrapping_add((*src).nsecfsyncsum);
        (*dst).rops = (*dst).rops.wrapping_add((*src).rops);
        (*dst).wops = (*dst).wops.wrapping_add((*src).wops);
        (*dst).fsyncops = (*dst).fsyncops.wrapping_add((*src).fsyncops);
        if (*src).nsecreadmax > (*dst).nsecreadmax {
            (*dst).nsecreadmax = (*src).nsecreadmax;
        }
        if (*src).nsecwritemax > (*dst).nsecwritemax {
            (*dst).nsecwritemax = (*src).nsecwritemax;
        }
        if (*src).nsecfsyncmax > (*dst).nsecfsyncmax {
            (*dst).nsecfsyncmax = (*src).nsecfsyncmax;
        }
    }
}
#[inline]
unsafe extern "C" fn hdd_stats_binary_pack(mut buff: *mut *mut uint8_t, mut r: *mut hddstats) {
    unsafe {
        put64bit(buff, (*r).rbytes);
        put64bit(buff, (*r).wbytes);
        put64bit(buff, (*r).nsecreadsum.wrapping_div(1000 as uint64_t));
        put64bit(buff, (*r).nsecwritesum.wrapping_div(1000 as uint64_t));
        put64bit(buff, (*r).nsecfsyncsum.wrapping_div(1000 as uint64_t));
        put32bit(buff, (*r).rops);
        put32bit(buff, (*r).wops);
        put32bit(buff, (*r).fsyncops);
        put32bit(
            buff,
            (*r).nsecreadmax.wrapping_div(1000 as uint64_t) as uint32_t,
        );
        put32bit(
            buff,
            (*r).nsecwritemax.wrapping_div(1000 as uint64_t) as uint32_t,
        );
        put32bit(
            buff,
            (*r).nsecfsyncmax.wrapping_div(1000 as uint64_t) as uint32_t,
        );
    }
}
#[inline]
unsafe extern "C" fn hdd_create_filename(
    mut fname: *mut ::core::ffi::c_char,
    mut fpath: *const ::core::ffi::c_char,
    mut pathid: uint16_t,
    mut chunkid: uint64_t,
    mut version: uint32_t,
) {
    unsafe {
        if (pathid as ::core::ffi::c_int) < 256 as ::core::ffi::c_int {
            let mut pl: ::core::ffi::c_int = strlen(fpath) as ::core::ffi::c_int;
            if pl > PATH_MAX - 100 as ::core::ffi::c_int {
                snprintf(
                    fname as *mut ::core::ffi::c_char,
                    PATH_MAX as size_t,
                    b"/dev/null\0".as_ptr() as *const ::core::ffi::c_char,
                );
            } else if pl > 0 as ::core::ffi::c_int
                && *fpath.offset((pl - 1 as ::core::ffi::c_int) as isize) as ::core::ffi::c_int
                    == '/' as ::core::ffi::c_int
            {
                snprintf(
                    fname as *mut ::core::ffi::c_char,
                    PATH_MAX as size_t,
                    b"%s%02hX/chunk_%016lX_%08X.mfs\0".as_ptr() as *const ::core::ffi::c_char,
                    fpath,
                    pathid as ::core::ffi::c_int,
                    chunkid,
                    version,
                );
            } else {
                snprintf(
                    fname as *mut ::core::ffi::c_char,
                    PATH_MAX as size_t,
                    b"%s/%02hX/chunk_%016lX_%08X.mfs\0".as_ptr() as *const ::core::ffi::c_char,
                    fpath,
                    pathid as ::core::ffi::c_int,
                    chunkid,
                    version,
                );
            }
            *fname.offset((PATH_MAX - 1 as ::core::ffi::c_int) as isize) = 0 as ::core::ffi::c_char;
        } else {
            snprintf(
                fname as *mut ::core::ffi::c_char,
                PATH_MAX as size_t,
                b"/dev/null\0".as_ptr() as *const ::core::ffi::c_char,
            );
        };
    }
}
