        let mut c: *mut chunk = ::core::ptr::null_mut::<chunk>();
        let mut ret: ::core::ffi::c_int = 0;
        let mut error: ::core::ffi::c_int = 0;
        let mut rcrcptr: *const uint8_t = ::core::ptr::null::<uint8_t>();
        let mut crc: uint32_t = 0;
        let mut bcrc: uint32_t = 0;
